impl Solution{pub fn search(a:Vec<i32>,t:i32)->bool{let(mut l,mut r)=(0i32,a.len()as i32-1);while l<=r{let m=(l+r)/2;if a[m as usize]==t{return true}if a[l as usize]==a[m as usize]&&a[m as usize]==a[r as usize]{l+=1;r-=1;continue}if a[l as usize]<=a[m as usize]{if a[l as usize]<=t&&t<a[m as usize]{r=m-1}else{l=m+1}}else{if a[m as usize]<t&&t<=a[r as usize]{l=m+1}else{r=m-1}}}false}}
